-- Produtos materiais extraidos da planilha fiscal enviada em 05/10/2026.
-- Os itens sem NCM fechado ficaram fora da NF-e modelo 55.
-- Todos exigem aprovacao contabil antes de uso em producao.


on conflict (empresa_id, codigo) do update set
  descricao = excluded.descricao, grupo = excluded.grupo, unidade = excluded.unidade, ncm = excluded.ncm, descricao_ncm = excluded.descricao_ncm, categoria_fiscal = excluded.categoria_fiscal, cfop_padrao = excluded.cfop_padrao, origem = excluded.origem, cst_icms = excluded.cst_icms, aliquota_icms = excluded.aliquota_icms, cst_pis = excluded.cst_pis, aliquota_pis = excluded.aliquota_pis, cst_cofins = excluded.cst_cofins, aliquota_cofins = excluded.aliquota_cofins, cest = excluded.cest, observacao_fiscal = excluded.observacao_fiscal, custo_padrao = excluded.custo_padrao, preco_venda = excluded.preco_venda, origem_catalogo = excluded.origem_catalogo, referencia_origem = excluded.referencia_origem, revisao_fiscal_pendente = excluded.revisao_fiscal_pendente, ativo = excluded.ativo, atualizado_em = current_timestamp;

